import React, { useCallback, useEffect, useState } from "react";
import { Container, Row, Col, Card, Button, Alert, Spinner, Table } from "react-bootstrap";
import { Link, useParams } from "react-router-dom";
import { FaArrowLeft, FaRedo, FaMapMarkerAlt } from "react-icons/fa";
import PageShell from "../components/PageShell";
import QualityBadge from "../components/QualityBadge";
import { waterAPI } from "../utils/api";

export default function SampleDetail() {
  const { id } = useParams();
  const [sample,setSample]=useState(null), [error,setError]=useState(""), [busy,setBusy]=useState(false);
  const load = useCallback(
    () => waterAPI.sample(id).then(r => setSample(r.data)).catch(() => setError("Could not load sample.")),
    [id]
  );
  useEffect(() => { load(); }, [load]);

  const recalc=async()=>{setBusy(true); try{await waterAPI.recalculate(id);await load();}catch(e){setError(e.response?.data?.error||"Recalculation failed.");}finally{setBusy(false);}};

  if(error) return <PageShell><Container className="py-5"><Alert variant="danger">{error}</Alert></Container></PageShell>;
  if(!sample) return <PageShell><Container className="py-5 text-center"><Spinner animation="border"/></Container></PageShell>;

  return <PageShell><Container className="py-5">
    <div className="d-flex justify-content-between align-items-start mb-4"><div><Link to="/samples" className="small text-decoration-none"><FaArrowLeft/> Back to samples</Link><h1 className="mt-2">{sample.sample_id}</h1><p className="text-muted mb-0"><FaMapMarkerAlt className="text-primary me-1"/>{sample.location_name}</p></div><Button onClick={recalc} disabled={busy} variant="outline-primary"><FaRedo className="me-1"/>{busy?"Calculating…":"Recalculate"}</Button></div>
    <Row className="g-4">
      <Col lg={4}><Card className="content-card h-100"><Card.Header>Sample information</Card.Header><Card.Body>
        <Info label="Collection date" value={sample.collection_date}/><Info label="Sample type" value={sample.sample_type}/><Info label="Coordinates" value={`${sample.latitude}, ${sample.longitude}`}/><Info label="pH" value={sample.ph_level ?? "—"}/><Info label="Temperature" value={sample.temperature ? `${sample.temperature} °C` : "—"}/><Info label="Notes" value={sample.notes || "—"}/>
      </Card.Body></Card></Col>
      <Col lg={8}><Card className="content-card h-100"><Card.Header className="d-flex justify-content-between"><span>HMPI result</span>{sample.hmpi_calculation && <QualityBadge category={sample.hmpi_calculation.quality_category}/>}</Card.Header><Card.Body>
        <div className="result-number mb-2">{sample.hmpi_value == null ? "—" : Number(sample.hmpi_value).toFixed(2)}</div>
        {sample.hmpi_calculation ? <p className="text-muted">Method {sample.hmpi_calculation.method_version} • {sample.hmpi_calculation.reference_profile}</p> : <p className="text-muted">No calculation stored yet.</p>}
      </Card.Body></Card></Col>
    </Row>
    <Card className="content-card mt-4"><Card.Header>Metal readings</Card.Header><Card.Body className="p-0"><Table responsive className="app-table mb-0"><thead><tr><th>Metal</th><th>Concentration</th><th>mg/L</th><th>Unit</th></tr></thead><tbody>{(sample.readings||[]).map(r=><tr key={r.id}><td>{r.metal_name} ({r.metal_type})</td><td>{r.concentration}</td><td>{Number(r.concentration_mg_l).toFixed(8)}</td><td>{r.unit}</td></tr>)}</tbody></Table></Card.Body></Card>
  </Container></PageShell>;
}
function Info({label,value}){return <div className="info-line"><span>{label}</span><strong>{value}</strong></div>}
