import React from "react";
import { Badge } from "react-bootstrap";

export default function QualityBadge({ category }) {
  if (!category) return <Badge bg="secondary">Not calculated</Badge>;
  const map = {
    excellent: ["success", "Excellent"],
    good: ["primary", "Good"],
    poor: ["warning", "Poor"],
    very_poor: ["orange", "Very Poor"],
    unsuitable: ["danger", "Unsuitable"],
  };
  const [variant, label] = map[category] || ["secondary", category];
  return <Badge bg={variant} className="quality-badge">{label}</Badge>;
}
